  ('bis-major-consumer-products-annexure-2-061', 'bis-major-consumer-products-annexure-2', 'Solar Photovoltaics, Systems, Devices and Components', NULL, 5, 'Official BIS compulsory-marking entry. Product: Power converters for use in photovoltaic power system. Indian Standard: IS 16221 (Part 2) :2015. Category: Solar Photovoltaics, Systems, Devices and Components. Standard title: Safety of Power Converters for use in Photovoltaic Power Systems Part 1- General Requirements Safety of Power Converters for Use in Photovoltaic Power Systems Part 2-Particular Requirements for Inverters.', ARRAY['Power converters for use in photovoltaic power system', 'IS 16221 (Part 2) :2015', 'Safety of Power Converters for use in Photovoltaic Power Systems Part 1- General Requirements Safety of Power Converters for Use in Photovoltaic Power Systems Part 2-Particular Requirements for Inverters', 'Solar Photovoltaics, Systems, Devices and Components', 'compulsory marking']::TEXT[], '{"recordKind":"compulsory_product","product":"Power converters for use in photovoltaic power system","standardNumber":"IS 16221 (Part 2) :2015","standardTitle":"Safety of Power Converters for use in Photovoltaic Power Systems Part 1- General Requirements Safety of Power Converters for Use in Photovoltaic Power Systems Part 2-Particular Requirements for Inverters","category":"Solar Photovoltaics, Systems, Devices and Components","listName":"List of Major Consumer Products Notified for Compulsory Marking","sourceSequence":61}'::jsonb),
  ('bis-major-consumer-products-annexure-2-062', 'bis-major-consumer-products-annexure-2', 'Solar Photovoltaics, Systems, Devices and Components', NULL, 5, 'Official BIS compulsory-marking entry. Product: Utility -Interconnected Photovoltaic inverters. Indian Standard: IS 16169:2019. Category: Solar Photovoltaics, Systems, Devices and Components. Standard title: Test Procedure of Islanding Prevention Measures for Utility-Interconnected Photovoltaic Inverters.', ARRAY['Utility -Interconnected Photovoltaic inverters', 'IS 16169:2019', 'Test Procedure of Islanding Prevention Measures for Utility-Interconnected Photovoltaic Inverters', 'Solar Photovoltaics, Systems, Devices and Components', 'compulsory marking']::TEXT[], '{"recordKind":"compulsory_product","product":"Utility -Interconnected Photovoltaic inverters","standardNumber":"IS 16169:2019","standardTitle":"Test Procedure of Islanding Prevention Measures for Utility-Interconnected Photovoltaic Inverters","category":"Solar Photovoltaics, Systems, Devices and Components","listName":"List of Major Consumer Products Notified for Compulsory Marking","sourceSequence":62}'::jsonb),
  ('bis-hallmark-faq-gold-standards', 'bis-hallmarking-faq-official', 'Indian Standards on Hallmarking', NULL, NULL, 'The BIS Hallmarking FAQ lists IS 1417:2016 for gold and gold alloys, jewellery and artefacts - fineness and marking - specification.', ARRAY['IS 1417:2016', 'gold', 'jewellery', 'hallmarking', 'fineness']::TEXT[], '{"recordKind":"hallmarking_fact","standardNumber":"IS 1417:2016","product":"Gold jewellery and artefacts","standardTitle":"Gold and Gold Alloys, Jewellery/Artefacts - Fineness and Marking - Specification"}'::jsonb),
  ('bis-hallmark-faq-gold-grades', 'bis-hallmarking-faq-official', 'Permitted gold grades', NULL, NULL, 'The BIS Hallmarking FAQ says IS 1417:2016 permits six gold hallmarking grades: 14K (585), 18K (750), 20K (833), 22K (916), 23K (958), and 24KS (995).', ARRAY['14K585', '18K750', '20K833', '22K916', '23K958', '24KS995', 'gold purity']::TEXT[], '{"recordKind":"hallmarking_fact","label":"Permitted gold grades","value":"14K (585), 18K (750), 20K (833), 22K (916), 23K (958), 24KS (995)"}'::jsonb),
  ('bis-hallmark-faq-huid', 'bis-hallmarking-faq-official', 'HUID verification', NULL, NULL, 'BIS says HUID is a six-digit alphanumeric Hallmark Unique Identification number, unique for each hallmarked item and traceable. Consumers can verify it in the BIS Care App using Verify HUID.', ARRAY['HUID', 'Verify HUID', 'BIS Care App', 'hallmark', 'six digit alphanumeric']::TEXT[], '{"recordKind":"hallmarking_fact","label":"Official HUID verification","value":"Use Verify HUID in the BIS Care App"}'::jsonb),
  ('bis-lims-is1417-laboratories', 'bis-lims-is-1417', 'Laboratories with IS 1417 facilities', NULL, NULL, 'BIS LIMS lists IS 1417:2016 facilities at Northern Regional Laboratory, Bengaluru Branch Laboratory, Central Laboratory, Hyderabad Branch Laboratory, Western Regional Laboratory, Jammu Kashmir Branch Laboratory, Patna Branch Laboratory, Southern Regional Laboratory, and Eastern Regional Laboratory. Users should open BIS LIMS to confirm current scope and availability.', ARRAY['IS 1417', 'gold testing laboratory', 'gold purity lab', 'BIS lab', 'jewellery testing']::TEXT[], '{"recordKind":"laboratory_fact","standardNumber":"IS 1417:2016","label":"BIS laboratories listed","value":"NRL, BNBL, CL, HYBL, WRL, JKBL, PBL, SRL, ERL"}'::jsonb),
  ('bis-lims-is1417-sample-quantity', 'bis-lims-is-1417', 'Sample quantity and test facilities', NULL, NULL, 'BIS LIMS lists a minimum 1.5 gram sample for 9K gold jewellery and a minimum 1 gram sample for other gold jewellery grades at multiple BIS laboratories. Scope, charges, and availability must be checked on the live LIMS page.', ARRAY['gold sample quantity', '1.5 gram', '1 gram', 'IS 1417 testing', 'testing charges']::TEXT[], '{"recordKind":"laboratory_fact","standardNumber":"IS 1417:2016","label":"Minimum sample quantity","value":"1.5 g for 9K; 1 g for other jewellery grades"}'::jsonb);
